# 고정 크기 청크(겹침 있음/없음)와 문장 단위 청크를 같은 글에 적용해 본다
import re
text = ("Grading. The project milestone is due Week 6, Thursday 11:59pm. "
        "Late days may not be applied to the milestone. The final report is due Week 10.")
words = text.split()

def fixed(size, overlap=0):
    step = size - overlap
    return [" ".join(words[i:i + size]) for i in range(0, len(words), step)
            if words[i:i + size]]

def by_sentence():
    return [s for s in re.split(r"(?<=\.)\s+", text) if s]

for name, chunks in [("fixed 8", fixed(8)), ("fixed 8 / overlap 2", fixed(8, 2)),
                     ("sentence", by_sentence())]:
    print(f"== {name}: {len(chunks)} chunks")
    for c in chunks:
        print("  |", c)
q = "late days milestone"
for c in fixed(8):
    print(sum(w.lower().strip(".,") in q.split() for w in c.split()), c)

# Hit@k · Failed@k · MRR@k · Recall@k 와 RRF 를 작은 예로 확인
runs = {  # 질의별 검색 결과(순위순)와 정답 집합
    "q1": (["d3", "d7", "d1", "d9", "d2"], {"d1", "d2"}),
    "q2": (["d4", "d5", "d6", "d8", "d0"], {"d9"}),
    "q3": (["d2", "d8", "d4", "d1", "d6"], {"d2", "d4", "d5"}),
}
def hit(k):    return sum(bool(set(r[:k]) & R) for r, R in runs.values()) / len(runs)
def mrr(k):
    tot = 0
    for r, R in runs.values():
        tot += next((1 / (i + 1) for i, d in enumerate(r[:k]) if d in R), 0)
    return tot / len(runs)
def recall(k): return sum(len(set(r[:k]) & R) / len(R) for r, R in runs.values()) / len(runs)
for k in (1, 3, 5):
    print(f"k={k} Hit={hit(k):.3f} Failed={1-hit(k):.3f} MRR={mrr(k):.3f} Recall={recall(k):.3f}")

def rrf(lists, k=60):
    score = {}
    for lst in lists:
        for rank, d in enumerate(lst, 1):
            score[d] = score.get(d, 0) + 1 / (k + rank)
    return sorted(score.items(), key=lambda x: -x[1])
bm25 = ["A", "B", "C"]; dense = ["C", "A", "D"]
for d, s in rrf([bm25, dense]): print(d, round(s, 5))
